<h1>کاربران مدیریت</h1><?php if($error): ?><p class="flash flash-error"><?= CHtml::encode($error) ?></p><?php endif; ?><section class="panel"><?php foreach($users as $user): ?>
<?= CHtml::beginForm('','post',array('class'=>'form-row')) ?><?= CHtml::hiddenField('id',$user->id,array('id'=>false)) ?><div class="field"><label>نام</label><?= CHtml::textField('name',$user->name,array('id'=>false,'required'=>true)) ?></div><div class="field"><label>ایمیل</label><?= CHtml::emailField('email',$user->email,array('id'=>false,'required'=>true)) ?></div><div class="field"><label>نقش</label><?= CHtml::dropDownList('role',$user->role,AdminUserController::roles(),array('id'=>false)) ?></div><div class="field"><label>رمز جدید؛ خالی یعنی بدون تغییر</label><?= CHtml::passwordField('password','',array('id'=>false,'autocomplete'=>'new-password')) ?></div><label><?= CHtml::checkBox('is_active',$user->is_active,array('id'=>false,'value'=>'1')) ?> فعال</label><?= CHtml::submitButton('ذخیره',array('class'=>'btn btn-outline')) ?><?= CHtml::endForm() ?><?php endforeach; ?></section>
<section class="panel"><h2>کاربر جدید</h2><?= CHtml::beginForm('','post') ?><div class="form-row"><div class="field"><label>نام</label><?= CHtml::textField('name','',array('required'=>true)) ?></div><div class="field"><label>ایمیل</label><?= CHtml::emailField('email','',array('required'=>true)) ?></div><div class="field"><label>رمز حداقل ۱۲ کاراکتر</label><?= CHtml::passwordField('password','',array('required'=>true,'minlength'=>12,'autocomplete'=>'new-password')) ?></div><div class="field"><label>نقش</label><?= CHtml::dropDownList('role','content',AdminUserController::roles()) ?></div></div><?= CHtml::hiddenField('is_active','1') ?><?= CHtml::submitButton('ساخت کاربر',array('class'=>'btn btn-primary')) ?><?= CHtml::endForm() ?></section>
